-- =============================================================================
-- SmartPick Database Schema & Master Seed Script (180 Products)
-- Categories: Laptops (100), Mobiles (30), TVs (30), Smartwatches (20)
-- =============================================================================

CREATE DATABASE IF NOT EXISTS smartpick CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smartpick;

CREATE TABLE IF NOT EXISTS products (
    id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    brand VARCHAR(255) NULL,
    category VARCHAR(255) NULL,
    price DECIMAL(38,2) NULL,
    processor VARCHAR(255) NULL,
    ram_gb INT NULL,
    storage_gb INT NULL,
    gpu VARCHAR(255) NULL,
    display_size DECIMAL(38,2) NULL,
    battery_wh DECIMAL(38,2) NULL,
    rating DECIMAL(38,2) NULL,
    image_url TEXT NULL,
    resolution VARCHAR(255) NULL,
    has_gps BOOLEAN NULL,
    battery_life_days INT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

ON DUPLICATE KEY UPDATE
  name = VALUES(name),
  brand = VALUES(brand),
  category = VALUES(category),
  price = VALUES(price),
  processor = VALUES(processor),
  ram_gb = VALUES(ram_gb),
  storage_gb = VALUES(storage_gb),
  gpu = VALUES(gpu),
  display_size = VALUES(display_size),
  battery_wh = VALUES(battery_wh),
  rating = VALUES(rating),
  image_url = VALUES(image_url),
  resolution = VALUES(resolution),
  has_gps = VALUES(has_gps),
  battery_life_days = VALUES(battery_life_days);

-- Verification query
SELECT category, COUNT(*) as count FROM products GROUP BY category;
